    inline void write(BinaryWriter& writer, const observe::BookView& value)
    {
        writer.number(value.symbolId);
        writer.boolean(value.bestBid.has_value());
        if (value.bestBid)
        {
            write(writer, *value.bestBid);
        }
        writer.boolean(value.bestAsk.has_value());
        if (value.bestAsk)
        {
            write(writer, *value.bestAsk);
        }
        writer.number<std::uint64_t>(value.bidLevels);
        writer.number<std::uint64_t>(value.askLevels);
    }

    inline observe::BookView readBookView(BinaryReader& reader)
    {
        observe::BookView value{};
        value.symbolId = reader.number<SymbolId>();
        if (reader.boolean())
        {
            value.bestBid = readQuote(reader);
        }
        if (reader.boolean())
        {
            value.bestAsk = readQuote(reader);
        }
        value.bidLevels = readSize(reader);
        value.askLevels = readSize(reader);
        return value;
    }

