        writer.number<std::uint64_t>(value.managedPositions);
        writer.number<std::uint64_t>(value.markets);
        writer.number<std::uint64_t>(value.automaticLiquidationBudget);
        writer.boolean(value.restingOrders.has_value());
        if (value.restingOrders)
        {
            writer.number<std::uint64_t>(*value.restingOrders);
        }
        writer.number(value.nextOrderId);
        writer.number(value.nextPositionId);
        writer.number(value.oldestTrade);
        writer.number(value.newestTrade);
        writer.number(value.oldestContractEvent);
        writer.number(value.newestContractEvent);
